package com.example.riskplatform.controller;import com.example.riskplatform.common.ApiResponse;import com.example.riskplatform.dto.Requests.*;import com.example.riskplatform.entity.*;import com.example.riskplatform.service.SystemService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/system") @RequiredArgsConstructor public class SystemController{private final SystemService s;@GetMapping("/users") @PreAuthorize("hasAuthority('system:user:read')")public ApiResponse<List<SysUser>>users(){return ApiResponse.ok(s.users());}@PostMapping("/users") @PreAuthorize("hasAuthority('system:user:write')")public ApiResponse<SysUser>create(@Valid @RequestBody CreateUserRequest r){return ApiResponse.ok(s.createUser(r));}@PutMapping("/users/{id}/roles") @PreAuthorize("hasAuthority('system:user:write')")public ApiResponse<Void>roles(@PathVariable Long id,@Valid @RequestBody AssignRolesRequest r){s.assignRoles(id,r.getRoleIds());return ApiResponse.ok();}@GetMapping("/roles") @PreAuthorize("hasAuthority('system:role:read')")public ApiResponse<List<SysRole>>roles(){return ApiResponse.ok(s.roles());}@GetMapping("/departments")public ApiResponse<List<SysDepartment>>departments(){return ApiResponse.ok(s.departments());}}
